architecture.h4_f:
msg = CBOR{v:1, tèks, reply_to, sent_at}
ct = AES-GCM-256-Ankripte (k, nonce, msg, aad = room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, tèks, reply_to?, thread_id?, mentions?, sent_at}
ct = AES-GCM-256-Ankripte (kle_chanm, nonce, pt, aad = hex (id_chanm))
fil = CBOR{
  v:1,
  ciphertext: hex(ct), // longè varyab
  nonce: èg (12 B),
  sender_pseudo: hex(16 B),
  voye_nan: unix_ms
}

cryptoWire.h5_f:
ekstèn = CBOR{
  source_node: hex32,
  target_user: int64,
  inner_ciphertext: bytes,
  inner_nonce: bytes,
  voye_nan: unix_ms
}
sig = Ed25519-Sign (source_priv, ekstèn)
POST /federation/deliver { anvlòp: deyò, sig: hex64 }

auth.h1_f:
POST /api/otantifikasyon/anrejistre
  { non itilizatè, modpas, x25519_public_key, display_name, telefòn?, imèl?, avatar_emoji }

Repons 201 Kreye:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token payload:
  { sub: user_id, jti: device_id, tip: "aksè", eksp: kounye a + 15min }
chajman refresh_token:
  { sub: user_id, jti: device_id, tip: "refresh", eksp: kounye a + 30d }

HS256-siyen ak sekrè 64-byte node a soti nan .env

auth.h4_f:
register_begin(): challenge = rand(32)
                    opsyon = { rp.id, user.id, pubKeyCredParams, challenge }
                    opsyon retounen

register_finish(atestasyon):
  verifye atestasyon kont TPM / Secure anklav rasin CA
  magazen { credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/otantifikasyon/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → nouvo aparèy anrejistre; JWT yo tounen.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Ankripte (key_room, nonce, CBOR_payload, aad = room_id)

Fan-out ankadreman: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {load_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalize {plain_blake3}
            ← 201 {file_id, url}
TTL sou ki poko fini: 24 h

files.h4_f:
deny_list = {
  "aplikasyon/x-dosexec",
  "aplikasyon/x-sharedlib",
  "aplikasyon/x-mach-binè",
}
si magic.from_buffer(buf[:1024]) nan deny_list: retounen 415

presence.h1_f:
kliyan: sou premye frap → voye {type:"t", eta:"kòmanse"}
         pa plis voye pou 3 s sof si eta chanje
         10 s apre dènye frape → voye {type:"t", eta:"stop"}
reseptè: oto-sispann 10 s apre dènye "kòmanse" si pa gen okenn "sispann" te rive

calls.h1_f:
POST /api/calls/{room_id}/start {videyo, odyo} → call_id
WS emisyon {type:"c", kind:"invite", call_id}
WS emisyon {type:"c", kalite:"offer", sdp}
WS emisyon {type:"c", kalite:"reponn", sdp}
WS emisyon {type:"c", kalite:"kandida",glas} × N
POST /api/calls/{call_id}/end

federation.h2_f:
anvlòp = {
  source_node: hex32,
  target_user : int64,
  inner_ciphertext: bytes,
  inner_nonce : bytes,
  sent_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(anvlòp))
POST /federation/deliver { anvlòp, sig }

gossip.h3_f:
reklam = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(piblisite))
chaj tripotay: [..., {ad, sig}, ...]

reseptè: verifye sig kont ad.pubkey → magazen si ok
adisyonèl: PoW nan 2^18 zewo dirijan sou {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template ak {
  o aza = o aza nou an,
  server_name = non host nou an (oswa ECH-vlope),
  session_id = id sesyon nou an,
}
JA4 = t13d_xxxx_xxxx_xxxx (koresponn ak aktyèl Chrome stab)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {non: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domèn(t) = baz32( SHA256(grenn ∥ YYYY-MM-DD) )[:16] + ".egzanp"

push.h4_f:
iOS NSE: didReceive (demann) { decrypt (request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
zouti = siy_zouti
input = sous pyebwa, keys/release.key
manifest = {
  vèsyon: "0.1.0",
  bati_nan: unix_ms,
  dosye: [{chemen, sha256, gwosè}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
pwodiksyon = INTEGRITY.sig.json = {manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
kreye: POST /api/bots {username, display_name, code}
          → {bot_id, token, pubkey}
kouri: an-pwosesis (kowotine andedan ne)
      OR ekstèn (long-poll /api/bots/{id}/updates, token-auth'd)
mesaj: {tèks, siyati: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
sou /kòmanse {
  emèt "Byenveni, {ctx.first_name}"
}
sou / ajoute <item> {
